62	    public async Task<(IssueInviteResponse Response, bool IsNew)> IssueAsync(
63	        string email,
64	        Guid issuedByUserId,
65	        SystemRole callerRole,
66	        string frontendBaseUrl,
67	        CancellationToken cancellationToken = default)
68	    {
69	        Verify.That(email).IsNotNull().IsNotEmpty();
70	        Verify.That(issuedByUserId).IsNotDefault();
71	        Verify.That(frontendBaseUrl).IsNotNull().IsNotEmpty();
72	
73	        if (callerRole != SystemRole.Admin)
74	            throw new ForbiddenException("invite.forbidden", "Only admins can issue invitations.");
75	
76	        return await RetryPolicy.ExecuteAsync(async ct =>
77	        {
78	            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
79	            try
80	            {
81	                var existing = await _invitationRepository.FindActiveByEmailAsync(email, tx);
82	                if (existing is not null)
83	                {
84	                    var refreshToken = InvitationToken.Generate();
85	                    var newExpiry = DateTimeOffset.UtcNow.AddDays(7);
86	                    await _invitationRepository.RefreshTokenAsync(
87	                        existing.Id, refreshToken.Hash, newExpiry, tx);
88	                    tx.Commit();
89	                    _logger.LogInformation(
90	                        "Active invitation refreshed by {IssuedByUserId}", issuedByUserId);
91	                    return (InvitationTransforms.ToResponse(refreshToken.Raw, newExpiry, frontendBaseUrl), false);
92	                }
93	
94	                var registeredUser = await _userRepository.FindByEmailAsync(email, tx);
95	                if (registeredUser is not null)
96	                    throw new ConflictException(
97	                        "invite.already_registered", "This email address is already registered.");
98	
99	                var token = InvitationToken.Generate();
100	                var issuedAt = DateTimeOffset.UtcNow;
101	                var invitation = new Invitation(
102	                    id: Guid.NewGuid(),
103	                    email: email,
104	                    issuedByUserId: issuedByUserId,
105	                    tokenHash: token.Hash,
106	                    issuedAt: issuedAt,
107	                    expiresAt: issuedAt.AddDays(7),
108	                    consumedAt: null,
109	                    consumedByUserId: null);
110	
111	                await _invitationRepository.InsertAsync(invitation, tx);
112	
113	                var authEvent = new AuthEvent(
114	                    Id: Guid.NewGuid(),
115	                    OccurredAt: issuedAt,
116	                    EventType: AuthEventType.InvitationIssued,
117	                    UserId: issuedByUserId,
118	                    Outcome: "success");
119	                await _authEventRepository.RecordAsync(authEvent, tx);
120	
121	                tx.Commit();
122	
123	                _logger.LogInformation(
124	                    "Invitation issued by {IssuedByUserId}", issuedByUserId);
125	
126	                return (InvitationTransforms.ToResponse(invitation, token.Raw, frontendBaseUrl), true);
127	            }
128	            catch
129	            {
130	                tx.Rollback();
131	                throw;
132	            }
133	        }, cancellationToken);
134	    }
