136	    public async Task<User> AcceptAsync(
137	        string rawToken,
138	        string googleEmail,
139	        string googleSub,
140	        string displayName,
141	        CancellationToken cancellationToken = default)
142	    {
143	        Verify.That(rawToken).IsNotNull().IsNotEmpty();
144	        Verify.That(googleEmail).IsNotNull().IsNotEmpty();
145	        Verify.That(googleSub).IsNotNull().IsNotEmpty();
146	        Verify.That(displayName).IsNotNull().IsNotEmpty();
147	
148	        return await RetryPolicy.ExecuteAsync(async ct =>
149	        {
150	            var tokenHash = InvitationToken.HashRaw(rawToken);
151	            var acceptedAt = DateTimeOffset.UtcNow;
152	            var newUserId = Guid.NewGuid();
153	
154	            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
155	            try
156	            {
157	                // Atomic gate: marks consumed_at — serialises concurrent accepts.
158	                // consumed_by_user_id is set separately below (after user is created) to avoid
159	                // FK constraint violations in Microsoft.Data.Sqlite 10+ which enforces them by
160	                // default, unlike previous versions.
161	                var consumed = await _invitationRepository.TryConsumeAsync(tokenHash, acceptedAt, tx);
162	                if (!consumed)
163	                    throw new NotFoundException(
164	                        "invite.invalid",
165	                        "This invitation is no longer valid. Please request a new one.");
166	
167	                var invitation = await _invitationRepository.FindByTokenHashAsync(tokenHash, tx);
168	                if (invitation is null || !invitation.EmailMatches(googleEmail))
169	                    throw new BusinessRuleException(
170	                        "invite.email_mismatch",
171	                        "This invitation was issued to a different email address.");
172	
173	                var user = new User(
174	                    id: newUserId,
175	                    email: invitation.Email,
176	                    displayName: displayName,
177	                    systemRole: SystemRole.Standard,
178	                    googleSub: googleSub,
179	                    registeredAt: acceptedAt,
180	                    lastSignInAt: null);
181	
182	                await _userRepository.InsertAsync(user, tx);
183	
184	                // FK constraint satisfied now that the user row exists
185	                await _invitationRepository.RecordConsumerAsync(tokenHash, newUserId, tx);
186	
187	                var authEvent = new AuthEvent(
188	                    Id: Guid.NewGuid(),
189	                    OccurredAt: acceptedAt,
190	                    EventType: AuthEventType.InvitationAccepted,
191	                    UserId: newUserId,
192	                    Outcome: "success");
193	                await _authEventRepository.RecordAsync(authEvent, tx);
194	
195	                tx.Commit();
196	
197	                _logger.LogInformation("Invitation accepted by user {UserId}", newUserId);
198	                return user;
199	            }
200	            catch
201	            {
202	                tx.Rollback();
203	                throw;
204	            }
205	        }, cancellationToken);
206	    }
207	}
