1	using System.Data;
2	using System.Diagnostics;
3	using System.Reflection;
4	using Asp.Versioning;
5	using DbUp;
6	using DbUp.Sqlite;
7	using Kanban.AntiCorruption.Adapters;
8	using Kanban.Api.Auth;
9	using Kanban.Api.ErrorHandling;
10	using Kanban.Api.Health;
11	using Kanban.Api.Options;
12	using FluentValidation;
13	using Kanban.Business.Interfaces;
14	using Kanban.Business.Services;
15	using Kanban.Api.Endpoints;
16	using Kanban.Api.Infrastructure;
17	using Kanban.Api.Validators;
18	using Kanban.DataAccess;
19	using Kanban.DataAccess.Interfaces;
20	using Kanban.DataAccess.Repositories;
21	using Microsoft.AspNetCore.Authentication;
22	using Microsoft.AspNetCore.Authentication.Cookies;
23	using Microsoft.AspNetCore.Authentication.Google;
24	using Microsoft.AspNetCore.Authorization;
25	using Microsoft.AspNetCore.Diagnostics.HealthChecks;
26	using Microsoft.AspNetCore.HttpOverrides;
27	using Microsoft.AspNetCore.RateLimiting;
28	using Microsoft.Data.Sqlite;
29	using Microsoft.Extensions.Options;
30	using NetEscapades.AspNetCore.SecurityHeaders;
31	using Scalar.AspNetCore;
32	using CorsOptions = Kanban.Api.Options.CorsOptions;
33	
34	var builder = WebApplication.CreateBuilder(args);
35	
36	// ── Options — fail at boot if configuration is missing ────────────────────────
37	
38	builder.Services.AddOptions<GoogleAuthOptions>()
39	    .Bind(builder.Configuration.GetSection(GoogleAuthOptions.SectionName))
40	    .ValidateDataAnnotations()
41	    .ValidateOnStart();
42	
43	builder.Services.AddOptions<SeedOptions>()
44	    .Bind(builder.Configuration.GetSection(SeedOptions.SectionName))
45	    .ValidateDataAnnotations()
46	    .ValidateOnStart();
47	
48	builder.Services.AddOptions<CorsOptions>()
49	    .Bind(builder.Configuration.GetSection(CorsOptions.SectionName))
50	    .ValidateDataAnnotations()
51	    .ValidateOnStart();
52	
53	builder.Services.AddOptions<ConnectionStringOptions>()
54	    .Bind(builder.Configuration.GetSection(ConnectionStringOptions.SectionName))
55	    .ValidateDataAnnotations()
56	    .ValidateOnStart();
57	
58	// ── Database ──────────────────────────────────────────────────────────────────
59	
60	DapperConfiguration.RegisterTypeHandlers();
61	
62	// Resolve the connection string lazily from IOptions so that WebApplicationFactory
63	// configuration overrides (applied after builder services are registered) are honoured.
64	builder.Services.AddScoped<IDbConnection>(sp =>
65	{
66	    var opts = sp.GetRequiredService<IOptions<ConnectionStringOptions>>().Value;
67	    var conn = new SqliteConnection(opts.Kanban);
68	    conn.Open();
69	    using var cmd = conn.CreateCommand();
70	    cmd.CommandText = "PRAGMA busy_timeout = 5000;";
71	    cmd.ExecuteNonQuery();
72	    return conn;
73	});
74	
75	// ── Exception Handling ────────────────────────────────────────────────────────
76	
77	builder.Services.AddProblemDetails(options =>
78	{
79	    options.CustomizeProblemDetails = ctx =>
80	    {
81	        ctx.ProblemDetails.Extensions["traceId"] = Activity.Current?.Id;
82	        if (ctx.HttpContext.Response.StatusCode == StatusCodes.Status403Forbidden
83	            && !ctx.ProblemDetails.Extensions.ContainsKey("code"))
84	        {
85	            ctx.ProblemDetails.Title = "You are not registered to use this application.";
86	            ctx.ProblemDetails.Extensions["code"] = "user.not_registered";
87	        }
88	    };
89	});
90	builder.Services.AddExceptionHandler<DomainExceptionHandler>();
91	builder.Services.AddExceptionHandler<InfrastructureExceptionHandler>();
92	builder.Services.AddExceptionHandler<FallbackExceptionHandler>();
93	
94	// ── CORS ──────────────────────────────────────────────────────────────────────
95	
96	builder.Services.AddCors(options =>
97	    options.AddPolicy("KanbanWebApp", policy =>
98	        policy
99	            .WithOrigins(
100	                builder.Configuration
101	                    .GetSection("Cors:AllowedOrigins")
102	                    .Get<string[]>() ?? [])
103	            .WithMethods("GET", "POST", "PUT", "DELETE", "PATCH", "OPTIONS")
104	            .AllowAnyHeader()
105	            .WithExposedHeaders("X-Correlation-Id", "api-supported-versions")));
106	
107	// ── Authentication & Authorization ───────────────────────────────────────────
108	
109	builder.Services.AddScoped<ICurrentUserService, CurrentUserService>();
110	builder.Services.AddScoped<IAuthService, AuthService>();
111	builder.Services.AddScoped<IInvitationService, InvitationService>();
112	builder.Services.AddSingleton<IDbConnectionFactory, SqliteConnectionFactory>();
113	builder.Services.AddScoped<GoogleIdentityAdapter>();
114	builder.Services.AddScoped<IUserRepository, UserRepository>();
115	builder.Services.AddScoped<IAuthEventRepository, AuthEventRepository>();
116	builder.Services.AddScoped<IInvitationRepository, InvitationRepository>();
117	builder.Services.AddValidatorsFromAssemblyContaining<IssueInviteRequestValidator>();
118	builder.Services.AddHttpContextAccessor();
119	builder.Services.AddScoped<IAuthorizationHandler, RegisteredUserHandler>();
120	
121	builder.Services.AddAuthentication(options =>
122	    {
123	        options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
124	        options.DefaultChallengeScheme = GoogleDefaults.AuthenticationScheme;
125	    })
126	    .AddCookie(options =>
127	    {
128	        options.LoginPath = "/api/v1/auth/signin";
129	        options.Events.OnRedirectToLogin = ctx =>
130	        {
131	            ctx.Response.StatusCode = StatusCodes.Status401Unauthorized;
132	            return Task.CompletedTask;
133	        };
134	        options.Events.OnRedirectToAccessDenied = ctx =>
135	        {
136	            ctx.Response.StatusCode = StatusCodes.Status403Forbidden;
137	            return Task.CompletedTask;
138	        };
139	    })
140	    .AddGoogle(options =>
141	    {
142	        var googleOpts = builder.Configuration
143	            .GetSection(GoogleAuthOptions.SectionName)
144	            .Get<GoogleAuthOptions>()!;
145	        options.ClientId = googleOpts.ClientId;
146	        options.ClientSecret = googleOpts.ClientSecret;
147	        options.Events.OnTicketReceived = async ctx =>
148	        {
149	            var adapter = ctx.HttpContext.RequestServices
150	                .GetRequiredService<GoogleIdentityAdapter>();
151	            var authService = ctx.HttpContext.RequestServices
152	                .GetRequiredService<IAuthService>();
153	
154	            if (ctx.Principal is not null)
155	            {
156	                var identity = adapter.Extract(ctx.Principal);
157	                var claimsIdentity = ctx.Principal.Identity as System.Security.Claims.ClaimsIdentity;
158	                if (claimsIdentity is not null)
159	                {
160	                    await authService.HandleSignInAsync(
161	                        identity.Sub,
162	                        identity.Email,
163	                        claimsIdentity,
164	                        ctx.HttpContext.RequestAborted);
165	                }
166	            }
167	        };
168	    });
169	
170	builder.Services.AddAuthorizationBuilder()
171	    .AddPolicy("RegisteredUser", policy => policy
172	        .RequireAuthenticatedUser()
173	        .AddRequirements(new RegisteredUserRequirement()))
174	    .AddPolicy("Admin", policy => policy
175	        .RequireAuthenticatedUser()
176	        .RequireClaim("system_role", "admin"));
177	
178	// ── API Versioning ────────────────────────────────────────────────────────────
179	
180	builder.Services.AddApiVersioning(options =>
181	{
182	    options.DefaultApiVersion = new ApiVersion(1, 0);
183	    options.AssumeDefaultVersionWhenUnspecified = true;
184	    options.ReportApiVersions = true;
185	});
186	
187	// ── OpenAPI — development only ────────────────────────────────────────────────
188	
189	if (builder.Environment.IsDevelopment())
190	    builder.Services.AddOpenApi();
191	
192	// ── Health Checks ─────────────────────────────────────────────────────────────
193	
194	builder.Services.AddHealthChecks()
195	    .AddCheck("self", () => Microsoft.Extensions.Diagnostics.HealthChecks.HealthCheckResult.Healthy(), tags: ["live"])
196	    .AddCheck<DatabaseHealthCheck>("database", tags: ["ready"]);
197	
198	// ── Rate Limiting ─────────────────────────────────────────────────────────────
199	
200	builder.Services.AddRateLimiter(opts =>
201	{
202	    opts.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
203	    opts.OnRejected = async (ctx, _) =>
204	    {
205	        ctx.HttpContext.Response.Headers.RetryAfter = "60";
206	        await Results.Problem(
207	                title: "Too many requests",
208	                statusCode: StatusCodes.Status429TooManyRequests,
209	                detail: "Please retry after the Retry-After interval.")
210	            .ExecuteAsync(ctx.HttpContext);
211	    };
212	
213	    opts.AddFixedWindowLimiter("anonymous", o =>
214	    {
215	        o.PermitLimit = 10;
216	        o.Window = TimeSpan.FromMinutes(1);
217	    });
218	
219	    opts.AddSlidingWindowLimiter("authenticated", o =>
220	    {
221	        o.PermitLimit = 100;
222	        o.Window = TimeSpan.FromMinutes(1);
223	        o.SegmentsPerWindow = 6;
224	    });
225	
226	    opts.AddSlidingWindowLimiter("mutating", o =>
227	    {
228	        o.PermitLimit = 30;
229	        o.Window = TimeSpan.FromMinutes(1);
230	        o.SegmentsPerWindow = 6;
231	    });
232	});
233	
234	// ── Build ─────────────────────────────────────────────────────────────────────
235	
236	var app = builder.Build();
237	
238	// ── Migrations ────────────────────────────────────────────────────────────────
239	
240	// Read connection string post-build so WebApplicationFactory test overrides are resolved.
241	var connectionString = app.Configuration.GetConnectionString("Kanban")
242	    ?? throw new InvalidOperationException("ConnectionStrings:Kanban is required.");
243	
244	var seedOptions = app.Services.GetRequiredService<IOptions<SeedOptions>>().Value;
245	var migrationsAssembly = AppDomain.CurrentDomain.GetAssemblies()
246	    .FirstOrDefault(a => a.GetName().Name == "Kanban.Data")
247	    ?? Assembly.Load("Kanban.Data");
248	
249	var upgradeResult = DeployChanges.To
250	    .SqliteDatabase(connectionString)
251	    .WithScriptsEmbeddedInAssembly(
252	        migrationsAssembly,
253	        name => name.Contains("sqlite", StringComparison.OrdinalIgnoreCase))
254	    .WithVariables(new Dictionary<string, string>
255	    {
256	        ["AdminEmail"] = seedOptions.AdminEmail,
257	        ["AdminUserId"] = Guid.NewGuid().ToString("D"),
258	        ["SeedTimestamp"] = DateTimeOffset.UtcNow.ToString("o"),
259	    })
260	    .LogToConsole()
261	    .Build()
262	    .PerformUpgrade();
263	
264	if (!upgradeResult.Successful)
265	    throw new InvalidOperationException($"Database migration failed: {upgradeResult.Error?.Message}");
